package com.yeyamo_mobile.api.culture_service.domain;import jakarta.persistence.*;import java.util.UUID;@Entity@Table(name="culture_challenge_prompts")public class CultureChallengePrompt{@Id private UUID id;@Column(name="challenge_id",nullable=false)private UUID challengeId;@Column(nullable=false,columnDefinition="TEXT")private String prompt;@Column(name="language_code",length=35)private String languageCode;@Column(name="display_order",nullable=false)private int displayOrder;protected CultureChallengePrompt(){}public String getPrompt(){return prompt;}public String getLanguageCode(){return languageCode;}public int getDisplayOrder(){return displayOrder;}}
